pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 1 wei}("");
        assertTrue(success);
        uint initialBalance = address(c).balance;
        vm.prank(nonOwner);
        try c.sendMoney(nonOwner, 0) {
            assertTrue(false);
        } catch {
            assertTrue(true);
        }
    }
}
